import { cacheLife, cacheTag } from 'next/cache';

export type Product = {
  id: string;
  sku: string;
  name: string;
  category: string;
  price: number;
  inventory: number;
  availability: 'In stock' | 'Low stock' | 'Backorder' | 'Discontinued';
  status: 'Active' | 'Paused' | 'Archived';
  channel: 'DTC' | 'Wholesale' | 'Marketplace';
  updatedAt: Date;
};

type CatalogSnapshot = {
  refreshedAt: string;
  products: Product[];
  stats: {
    totalSkus: number;
    lowStock: number;
    outOfStock: number;
    paused: number;
    activeChannels: number;
  };
};

type ProductSeed = Omit<Product, 'updatedAt' | 'availability'> & {
  updatedHoursAgo: number;
};

const PRODUCT_SEEDS: ProductSeed[] = [
