/bin/bash -lc "cat <<'EOF' > /vercel/sandbox/app/globals.css
@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;600&family=Space+Grotesk:wght@400;500;600;700&display=swap');

:root {
  color-scheme: light;
  --bg: #f4efe7;
  --bg-accent: #f9f2d7;
  --panel: #ffffff;
  --panel-muted: rgba(255, 255, 255, 0.72);
  --ink: #1d1b17;
  --muted: #5d5a54;
  --accent: #136f63;
  --accent-strong: #0e4f47;
  --accent-warm: #d97732;
  --border: rgba(29, 27, 23, 0.12);
  --border-strong: rgba(29, 27, 23, 0.2);
  --shadow: 0 24px 60px rgba(26, 19, 7, 0.15);
  --font-body: 'Space Grotesk', 'Segoe UI', sans-serif;
  --font-display: 'Fraunces', 'Times New Roman', serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--ink);
  background: radial-gradient(circle at top left, #fff9e8 0%, #f4efe7 40%, #e9e2d4 100%);
  min-height: 100vh;
}

body::before {
  content: '';
  position: fixed;
  inset: 0;
  background: radial-gradient(circle at 15% 20%, rgba(19, 111, 99, 0.12), transparent 50%),
    radial-gradient(circle at 85% 10%, rgba(217, 119, 50, 0.12), transparent 45%),
    radial-gradient(circle at 80% 80%, rgba(17, 24, 39, 0.08), transparent 55%);
  pointer-events: none;
  z-index: -1;
}

.page {
  max-width: 1200px;
  margin: 0 auto;
  padding: 48px 28px 96px;
  display: flex;
  flex-direction: column;
  gap: 32px;
}

.page > * {
  animation: riseIn 0.6s ease both;
}

.page > *:nth-child(2) {
  animation-delay: 0.08s;
}

.page > *:nth-child(3) {
  animation-delay: 0.16s;
}

.page > *:nth-child(4) {
  animation-delay: 0.24s;
}

.page-header {
  display: flex;
  gap: 28px;
  align-items: stretch;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.24em;
  font-size: 0.68rem;
  font-weight: 600;
  color: var(--accent-strong);
  margin-bottom: 12px;
}

.page-header h1 {
  font-family: var(--font-display);
  font-size: clamp(2.2rem, 3vw, 3rem);
  margin: 0 0 12px;
}

.page-header p {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
  line-height: 1.6;
}

.sync-panel {
  margin-left: auto;
  min-width: 280px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 20px 22px;
  box-shadow: var(--shadow);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.sync-panel h2 {
  font-size: 1rem;
  margin: 0;
}

.button {
  border: 1px solid var(--border-strong);
  background: transparent;
  padding: 10px 18px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.95rem;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.button:focus-visible {
  outline: 2px solid var(--accent-warm);
  outline-offset: 2px;
}

.button--primary {
  background: var(--accent);
  color: #fff;
  border-color: transparent;
  box-shadow: 0 14px 30px rgba(19, 111, 99, 0.24);
}

.button--primary:hover {
  background: var(--accent-strong);
  transform: translateY(-1px);
}

.button--ghost {
  background: var(--panel-muted);
}

.sync-meta {
  font-size: 0.86rem;
  color: var(--muted);
}

.stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
}

.stat-card {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 18px;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  box-shadow: 0 18px 40px rgba(26, 19, 7, 0.08);
}

.stat-card span {
  font-size: 0.8rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}

.stat-card strong {
  font-size: 1.8rem;
  font-weight: 600;
}

.filters {
  background: var(--panel);
  border-radius: 20px;
  border: 1px solid var(--border);
  padding: 18px;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
  box-shadow: 0 14px 36px rgba(26, 19, 7, 0.08);
}

.search-input {
  flex: 1 1 280px;
  background: #fff;
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  padding: 10px 16px;
  font-size: 0.95rem;
}

.chip-group {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.chip {
  border-radius: 999px;
  border: 1px solid var(--border);
  padding: 6px 12px;
  font-size: 0.82rem;
  background: #fffaf0;
  cursor: pointer;
}

.chip.active {
  background: var(--accent);
  color: #fff;
  border-color: transparent;
}

.actions {
  display: flex;
  gap: 8px;
}

.catalog {
  background: var(--panel);
  border-radius: 24px;
  border: 1px solid var(--border);
  padding: 20px;
  box-shadow: var(--shadow);
}

.catalog-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.catalog-header h2 {
  margin: 0;
  font-size: 1.2rem;
}

.table-wrap {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  min-width: 840px;
}

th {
  text-align: left;
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--muted);
  padding: 12px 8px;
  border-bottom: 1px solid var(--border);
}

td {
  padding: 14px 8px;
  border-bottom: 1px solid rgba(29, 27, 23, 0.08);
  font-size: 0.92rem;
}

tr:hover {
  background: rgba(19, 111, 99, 0.06);
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 999px;
  padding: 4px 10px;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.badge.in-stock {
  background: rgba(19, 111, 99, 0.16);
  color: var(--accent-strong);
}

.badge.low-stock {
  background: rgba(217, 119, 50, 0.2);
  color: #9a4f1d;
}

.badge.backorder {
  background: rgba(17, 24, 39, 0.16);
  color: #111827;
}

.badge.discontinued {
  background: rgba(148, 163, 184, 0.25);
  color: #475569;
}

.status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 600;
  color: var(--ink);
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: var(--accent);
}

.status.paused .status-dot {
  background: var(--accent-warm);
}

.status.archived .status-dot {
  background: #94a3b8;
}

@keyframes riseIn {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (max-width: 960px) {
  .page-header {
    flex-direction: column;
  }

  .sync-panel {
    margin-left: 0;
    width: 100%;
  }
}

@media (max-width: 720px) {
  .page {
    padding: 36px 20px 72px;
  }

  .filters {
    flex-direction: column;
    align-items: stretch;
  }

  .actions {
    width: 100%;
    justify-content: space-between;
  }

  table {
    min-width: 720px;
  }
}
EOF"
